mapper.select:
        SELECT

            COUNT(DISTINCT o.order_id) AS totalOrders,

            COALESCE(
                SUM(o.quantity),
                0
            ) AS totalQuantity,

            COALESCE(
                SUM(o.total_price),
                0
            ) AS totalSales,

            COALESCE(
    AVG(o.total_price),
    0
) AS averageOrderValue,

COALESCE(
    AVG(o.quantity),
    0
) AS averageSoldQuantity

        FROM orders o

        INNER JOIN products p
            ON o.product_id = p.product_id

        INNER JOIN categories c
            ON p.category_id = c.category_id

        INNER JOIN sellers s
            ON p.user_id = s.user_id



            INNER JOIN payments pay
                ON o.order_id = pay.order_id



        WHERE 1 = 1






            AND o.customer_id = #{customerId}








            AND p.user_id = #{sellerId}








            AND p.category_id = #{categoryId}








            AND p.product_id = #{productId}








            AND LOWER(p.product_name)
                LIKE CONCAT(
                    '%',
                    LOWER(#{productName}),
                    '%'
                )








            AND p.product_price >= #{minPrice}








            AND p.product_price <= #{maxPrice}








            AND o.quantity >= #{minQuantity}








            AND o.quantity <= #{maxQuantity}








            AND o.order_status = #{orderStatus}








            AND pay.payment_status = #{paymentStatus}








            AND o.order_date >= STR_TO_DATE(
                #{fromDate},
                '%Y-%m-%dT%H:%i'
            )








            AND o.order_date <= STR_TO_DATE(
                #{toDate},
                '%Y-%m-%dT%H:%i'
            )

SELECT

    c.category_id AS categoryId,

    c.category_name AS categoryName,

    COUNT(DISTINCT p.product_id) AS productCount,

    COALESCE(
        SUM(o.quantity),
        0
    ) AS quantitySold,

    COALESCE(
        SUM(o.total_price),
        0
    ) AS revenue

FROM categories c

INNER JOIN products p
    ON c.category_id = p.category_id

LEFT JOIN orders o
    ON p.product_id = o.product_id

WHERE 1 = 1






    AND p.user_id = #{sellerId}








    AND o.customer_id = #{customerId}








    AND c.category_id = #{categoryId}








    AND p.product_price >= #{minPrice}








    AND p.product_price <= #{maxPrice}








    AND o.quantity >= #{minQuantity}








    AND o.quantity <= #{maxQuantity}








    AND o.order_status = #{orderStatus}








    AND o.order_date >= STR_TO_DATE(
        #{fromDate},
        '%Y-%m-%dT%H:%i'
    )








    AND o.order_date <= STR_TO_DATE(
        #{toDate},
        '%Y-%m-%dT%H:%i'
    )




GROUP BY

    c.category_id,
    c.category_name

ORDER BY revenue DESC
